style.css:
@-moz-document url("https://www.google.com/"), url("https://www.google.it/"), url("https://www.google.com/?gws_rd=ssl"), url("https://www.google.it/?gws_rd=ssl"), url-prefix("https://www.google.com/webhp"), url-prefix("https://www.google.it/webhp") {
/* Sfondo principale */
    body {
        background: url(https://i.imgur.com/J7DQHfo.jpeg) center center fixed !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
    }

    /* Container centrale - rendilo trasparente per vedere lo sfondo */
    #main, .main, .o3j99 {
        background: transparent !important;
    }

    /* Logo Google - nascondi quello originale */
    .lnXdpd, img[alt*="Google"] {
        opacity: 0 !important;
        visibility: hidden !important;
    }

    /* Logo personalizzato - POSIZIONAMENTO CORRETTO */
    .k1zIA, .o3j99.ikrT4e.om7nvf {
        background-image: url(https://i.imgur.com/op3hUsR.png) !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-size: 275px 95px !important;
        height: 92px !important;
        width: 272px !important;
        position: relative !important;
        z-index: 999 !important;
    }

    /* Barra di ricerca */
    .gLFyf {
        background-color: rgba(255, 255, 255, 0.95) !important;
        border-radius: 24px !important;
        border: none !important;
        color: #000000 !important;
        font-family: "Mencken Std Bold Italic", Arial, sans-serif !important;
    }

    /* Container barra di ricerca */
    .RNNXgb {
        background-color: rgba(255, 255, 255, 0.1) !important;
        border: 1px solid rgba(255, 255, 255, 0.3) !important;
        border-radius: 24px !important;
        backdrop-filter: blur(10px) !important;
    }

    /* Font generale */
    body, input, button, div, span {
        font-family: "Mencken Std Bold Italic", Arial, sans-serif !important;
    }

    /* Footer - nascondi */
    #fbar, footer, .o3j99.LLD4me.LyIfbd {
        display: none !important;
    }
}
